"use strict";
const panels=[...document.querySelectorAll('[data-panel]')];function tab(id){panels.forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===id;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});}if(panels.length)tab(panels.find(p=>p.dataset.active==='1')?.id||panels[0].id);document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>tab(b.dataset.tab)));
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('keydown',event=>{const tabs=[...document.querySelectorAll('[data-tab]')];let index=tabs.indexOf(b);if(event.key==='ArrowRight')index=(index+1)%tabs.length;else if(event.key==='ArrowLeft')index=(index-1+tabs.length)%tabs.length;else if(event.key==='Home')index=0;else if(event.key==='End')index=tabs.length-1;else return;event.preventDefault();tab(tabs[index].dataset.tab);tabs[index].focus();}));
const qr=document.querySelector('[data-qr]');if(qr){const base='/realms/52okp/wechat/',tail=encodeURIComponent(qr.dataset.ticket)+'?key='+encodeURIComponent(qr.dataset.key),msg=qr.querySelector('[data-qr-message]'),img=qr.querySelector('img'),timer=document.querySelector('[data-countdown]');let stopped=false,failures=0;const stop=text=>{stopped=true;msg.textContent=text;msg.hidden=false;img.hidden=true;};const tick=()=>{const seconds=Math.max(0,Number(qr.dataset.expires)-Math.floor(Date.now()/1000));timer.textContent=seconds?'有效期 '+Math.floor(seconds/60)+' 分 '+seconds%60+' 秒':'登录码已过期';if(!seconds&&!stopped)stop('已过期，请点击刷新登录码');};tick();setInterval(tick,1000);
(async()=>{try{const response=await fetch(base+'qrcode/'+tail,{cache:'no-store',credentials:'same-origin'});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.message||'登录码获取失败，请稍后手动刷新');}const blob=await response.blob();if(!blob.type.startsWith('image/'))throw new Error('登录码格式错误，请联系管理员');if(stopped)return;const url=URL.createObjectURL(blob);img.onload=()=>URL.revokeObjectURL(url);img.onerror=()=>stop('登录码加载失败，请刷新');img.src=url;img.hidden=false;msg.hidden=true;poll();}catch(e){stop(e.message);}})();
async function poll(){if(stopped)return;try{const response=await fetch(base+'status/'+tail,{cache:'no-store',credentials:'same-origin'});if(response.status===429){msg.textContent='查询较频繁，稍后继续…';msg.hidden=false;setTimeout(poll,60000);return;}if(!response.ok)throw new Error('查询失败');const result=await response.json();failures=0;if(result.state==='CONFIRMED'){stopped=true;document.querySelector('#qr-finish').requestSubmit();return;}if(['EXPIRED','CANCELLED','CONSUMED'].includes(result.state)){stop(result.state==='EXPIRED'?'登录码已过期，请刷新':'请求已结束，请重新发起');return;}setTimeout(poll,3000);}catch(e){if(++failures>=3){stop('暂时无法查询确认结果，请刷新重试');return;}setTimeout(poll,3000*failures);}}}
document.querySelectorAll('[data-email-form]').forEach(form=>{const button=form.querySelector('[data-send-code]'),status=form.querySelector('[data-code-message]');button?.addEventListener('click',async()=>{const email=form.querySelector('[name=email]');if(!email.reportValidity())return;button.disabled=true;status.textContent='正在发送…';try{const body=new URLSearchParams({email:email.value,purpose:form.querySelector('[name=purpose]').value,csrf:form.querySelector('[name=csrf]').value});const response=await fetch('/email/send',{method:'POST',body,credentials:'same-origin'});const result=await response.json();if(!response.ok)throw new Error(result.message||'发送失败');status.textContent=result.message;let left=60;const timer=setInterval(()=>{left--;button.textContent=left+' 秒后重试';if(left<=0){clearInterval(timer);button.disabled=false;button.textContent='发送验证码';}},1000);}catch(e){status.textContent=e.message;button.disabled=false;}});});
if(document.querySelector('[data-update-task]')){const message=document.querySelector('[data-update-message]'),progress=document.querySelector('[data-update-progress]');let failures=0;async function updateStatus(){try{const r=await fetch('/admin/updates/status',{cache:'no-store',credentials:'same-origin'});if(r.status===503){message.textContent='维护窗口进行中，正在安装或恢复；请勿手工覆盖文件。';setTimeout(updateStatus,5000);return;}if(r.status===401||r.status===403){message.textContent='登录已失效，请重新登录查看更新结果。';return;}if(!r.ok)throw new Error();const result=await r.json();failures=0;if(result.job){message.textContent=result.job.message;progress.textContent=result.job.phase==='downloading'&&result.job.total?'已接收 '+result.job.bytes+' / '+result.job.total+' 字节':'';if(['complete','rolled_back','failed','recovery_required'].includes(result.job.phase))return;}setTimeout(updateStatus,4000);}catch(e){failures++;message.textContent='暂时无法获取更新状态，请稍后刷新查看结果；系统不会因此重复提交安装。';if(failures<15)setTimeout(updateStatus,5000);}}updateStatus();}

const loginRedirect=document.querySelector("a[data-login-redirect]");if(loginRedirect)window.location.replace(loginRedirect.href);

const applicationFilter=document.querySelector("[data-application-filter]");if(applicationFilter){const client=applicationFilter.querySelector("[name=client]"),relation=applicationFilter.querySelector("[name=relation]");client.addEventListener("change",()=>{relation.disabled=!client.value;if(!client.value)relation.value="all";});}
